#!/usr/bin/env bash
#
# Audits the built APK: package identity, SDK levels, declared permissions,
# accessibility wiring, launcher components and signature.
#
# Permission policy: the only permission allowed to exist is the signature-level,
# app-private broadcast guard that AndroidX injects at merge time. Anything else
# fails the build.
set -euo pipefail

APK="${1:-app/build/outputs/apk/debug/app-debug.apk}"
SDK="${ANDROID_HOME:-${ANDROID_SDK_ROOT:-}}"

# Auto-generated by androidx.core to protect its own internal broadcasts.
# protectionLevel=signature, so only this app's signature can hold it; it grants
# no access to user data, the network, or other apps.
ALLOWED_SELF_PERMISSION="com.quicklock.app.DYNAMIC_RECEIVER_NOT_EXPORTED_PERMISSION"

fail() { echo "FAIL: $*" >&2; exit 1; }
ok() { echo "OK:   $*"; }

[ -f "$APK" ] || fail "APK not found: $APK"
[ -n "$SDK" ] || fail "ANDROID_HOME / ANDROID_SDK_ROOT is not set"

find_tool() {
  local name="$1"
  # shellcheck disable=SC2012
  ls -1 "$SDK"/build-tools/*/"$name" 2>/dev/null | sort -V | tail -1
}

AAPT2="$(find_tool aapt2)"
APKSIGNER="$(find_tool apksigner)"
[ -x "$AAPT2" ] || fail "aapt2 not found under $SDK/build-tools"
[ -x "$APKSIGNER" ] || fail "apksigner not found under $SDK/build-tools"

echo "== APK =="
echo "path: $APK"
echo "size: $(du -h "$APK" | cut -f1)"

BADGING="$("$AAPT2" dump badging "$APK")"
TREE="$("$AAPT2" dump xmltree --file AndroidManifest.xml "$APK")"

echo
echo "== aapt2 dump badging =="
printf '%s\n' "$BADGING"
echo

PKG="$(printf '%s\n' "$BADGING" | sed -n "s/^package: name='\([^']*\)'.*/\1/p")"
VERSION_NAME="$(printf '%s\n' "$BADGING" | sed -n "s/.*versionName='\([^']*\)'.*/\1/p" | head -1)"
MIN_SDK="$(printf '%s\n' "$BADGING" | sed -n "s/^\(sdkVersion\|minSdkVersion\):'\([0-9]*\)'.*/\2/p" | head -1)"
TARGET_SDK="$(printf '%s\n' "$BADGING" | sed -n "s/^targetSdkVersion:'\([0-9]*\)'.*/\1/p" | head -1)"

echo "== Identity =="
echo "package: $PKG ($VERSION_NAME)"
echo "minSdk: $MIN_SDK  targetSdk: $TARGET_SDK"

[ "$PKG" = "com.quicklock.app" ] || fail "unexpected package name: $PKG"
[ "$MIN_SDK" = "26" ] || fail "unexpected minSdk: $MIN_SDK"
[ "$TARGET_SDK" = "35" ] || fail "unexpected targetSdk: $TARGET_SDK"
ok "package identity and SDK levels"

echo
echo "== Declared permissions =="
PERMS="$(printf '%s\n' "$BADGING" | sed -n "s/^uses-permission: name='\([^']*\)'.*/\1/p" || true)"
if [ -n "$PERMS" ]; then
  printf '%s\n' "$PERMS" | sed 's/^/  /'
fi

UNEXPECTED="$(printf '%s\n' "$PERMS" | grep -v -x -F "$ALLOWED_SELF_PERMISSION" || true)"
[ -z "$UNEXPECTED" ] || fail "unexpected permission(s) declared: $(printf '%s' "$UNEXPECTED" | tr '\n' ' ')"

if printf '%s\n' "$PERMS" | grep -q -x -F "$ALLOWED_SELF_PERMISSION"; then
  echo "  declaration:"
  printf '%s\n' "$TREE" | grep -A4 -F "\"$ALLOWED_SELF_PERMISSION\"" | sed 's/^/    /' || true
  printf '%s\n' "$TREE" | grep -A4 -F "$ALLOWED_SELF_PERMISSION" \
    | grep -F "protectionLevel" | grep -Eq "0x0*2|signature" \
    || fail "$ALLOWED_SELF_PERMISSION must be signature-level (protectionLevel)"
  ok "only the signature-level AndroidX broadcast guard is declared"
else
  ok "no <uses-permission> entries at all"
fi

echo
echo "== Components =="
for needle in \
  "com.quicklock.app.MainActivity" \
  "com.quicklock.app.LockActivity" \
  "com.quicklock.app.LockShortcutAlias" \
  "com.quicklock.app.accessibility.LockAccessibilityService" \
  "android.permission.BIND_ACCESSIBILITY_SERVICE" \
  "android.accessibilityservice.AccessibilityService" ; do
  printf '%s' "$TREE" | grep -qF "$needle" || fail "manifest is missing: $needle"
done
ok "activities, alias and accessibility service are wired"

printf '%s\n' "$TREE" | grep -A12 -F "LockShortcutAlias" | grep -qF "android.intent.category.LAUNCHER" \
  || fail "LockShortcutAlias is not a launcher entry"
ok "lock alias is a real launcher icon (Home screen + Dock)"

if printf '%s' "$TREE" | grep -qF "ProfileInstallReceiver"; then
  fail "AndroidX profileinstaller receiver was not stripped"
fi
ok "no AndroidX profileinstaller receiver"

# The accessibility config must not request event types or window content.
CONFIG_TREE="$("$AAPT2" dump xmltree --file res/xml/accessibility_service_config.xml "$APK")"
if printf '%s' "$CONFIG_TREE" | grep -qF "accessibilityEventTypes"; then
  fail "accessibility config declares accessibilityEventTypes"
fi
if printf '%s' "$CONFIG_TREE" | grep -qF "canRetrieveWindowContent"; then
  printf '%s' "$CONFIG_TREE" | grep -A1 -F "canRetrieveWindowContent" | grep -qF "0x0" \
    || fail "accessibility service can retrieve window content"
fi
if printf '%s' "$CONFIG_TREE" | grep -qF "canPerformGestures"; then
  printf '%s' "$CONFIG_TREE" | grep -A1 -F "canPerformGestures" | grep -qF "0x0" \
    || fail "accessibility service can perform gestures"
fi
ok "accessibility config: no events, no window content, no gestures"

echo
echo "== Signature =="
"$APKSIGNER" verify --print-certs "$APK" | sed -n '1,3p'
ok "APK signature verifies"

echo
echo "AUDIT PASSED"
